import{_ as t,o as a,c as r,ah as o}from"./chunks/framework.ChH6X6u6.js";const h=JSON.parse('{"title":"Votre espace élève","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/eleve/index.md","filePath":"src/guide/eleve/index.md"}'),n={name:"guide/eleve/index.md"};function s(i,e,l,u,c,d){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="votre-espace-eleve" tabindex="-1">Votre espace élève <a class="header-anchor" href="#votre-espace-eleve" aria-label="Permalink to &quot;Votre espace élève&quot;">​</a></h1><p>En tant qu&#39;élève, vous avez accès à votre propre tableau de bord dans ERA pour suivre vos notes, vos cours et vos documents. Ce guide présente tout ce que vous pouvez y consulter et y télécharger.</p><h2 id="votre-tableau-de-bord" tabindex="-1">Votre tableau de bord <a class="header-anchor" href="#votre-tableau-de-bord" aria-label="Permalink to &quot;Votre tableau de bord&quot;">​</a></h2><p>Une fois connecté, vous arrivez sur la page <strong>Mon portail</strong>, qui affiche votre nom, votre classe et votre site. Si vous n&#39;avez pas d&#39;inscription en cours, un message vous l&#39;indique et le reste des sections ne s&#39;affiche pas.</p><h2 id="vos-notes" tabindex="-1">Vos notes <a class="header-anchor" href="#vos-notes" aria-label="Permalink to &quot;Vos notes&quot;">​</a></h2><p>La section <strong>Notes</strong> liste vos moyennes par matière, période par période, avec votre moyenne annuelle affichée en haut de la section.</p><h2 id="telecharger-vos-bulletins" tabindex="-1">Télécharger vos bulletins <a class="header-anchor" href="#telecharger-vos-bulletins" aria-label="Permalink to &quot;Télécharger vos bulletins&quot;">​</a></h2><p>La section <strong>Bulletins</strong> liste vos bulletins publiés, période par période. Cliquez sur <strong>Télécharger</strong> en face d&#39;une période pour obtenir votre bulletin au format PDF. Un bulletin n&#39;apparaît ici qu&#39;une fois publié par l&#39;établissement.</p><h2 id="cahier-de-texte" tabindex="-1">Cahier de texte <a class="header-anchor" href="#cahier-de-texte" aria-label="Permalink to &quot;Cahier de texte&quot;">​</a></h2><p>La section <strong>Cahier de texte</strong> liste les cours donnés avec la date, la matière, le contenu et les devoirs demandés. Quand un cours a un document joint, un lien <strong>Pièce jointe</strong> apparaît en face de la ligne correspondante — cliquez pour l&#39;ouvrir.</p><h2 id="emploi-du-temps" tabindex="-1">Emploi du temps <a class="header-anchor" href="#emploi-du-temps" aria-label="Permalink to &quot;Emploi du temps&quot;">​</a></h2><p>La section <strong>Emploi du temps</strong> affiche votre planning hebdomadaire (jour, heure de début, heure de fin, matière). Pour l&#39;importer dans votre propre calendrier (Google Calendar, Apple Calendar, Outlook…) :</p><ol><li>Cliquez sur <strong>Exporter vers un calendrier</strong>.</li><li>Un fichier <code>.ics</code> est téléchargé ; ouvrez-le ou importez-le dans votre application de calendrier habituelle.</li></ol><h2 id="internat" tabindex="-1">Internat <a class="header-anchor" href="#internat" aria-label="Permalink to &quot;Internat&quot;">​</a></h2><p>Si vous êtes interne, une section <strong>Internat</strong> indique votre site, votre chambre et votre lit, ainsi que vos présences à l&#39;internat.</p><h2 id="presences-et-discipline" tabindex="-1">Présences et discipline <a class="header-anchor" href="#presences-et-discipline" aria-label="Permalink to &quot;Présences et discipline&quot;">​</a></h2><p>La section <strong>Présences</strong> affiche chaque jour avec son statut (Présent, Absent, Retard) et la note de justification s&#39;il y en a une. La justification d&#39;une absence se fait par votre parent ou tuteur depuis le portail parent — vous ne pouvez pas la faire vous-même depuis votre espace.</p><p>La section <strong>Incidents disciplinaires</strong> liste les incidents qui vous concernent (date, gravité, description, sanction), et <strong>Conseils de discipline</strong> ceux qui ont été tenus pour vous, avec leur décision.</p>',18)])])}const v=t(n,[["render",s]]);export{h as __pageData,v as default};
